{
  "didatica": [
    {
      "campo": "resolucao.antes.texto",
      "depois": "Em questão de vocabulário em contexto, vale o sentido que a expressão tem naquela frase, e não a tradução palavra por palavra. 'At least' costuma significar 'pelo menos'. Aqui ele vem depois de 'Or' e corrige o parágrafo anterior: o que foi descrito só valia até certo momento.",
      "motivo": "Frases mais simples; explica o papel de 'Or'."
    },
    {
      "campo": "resolucao.antes.formulas",
      "depois": [
        "at least = pelo menos, ao menos",
        "Or, at least, ... = ou, pelo menos, ... (a frase corrige o que veio antes)",
        "eventually = finalmente, no fim (não é 'eventualmente')",
        "in a way = de certo modo"
      ],
      "motivo": "Organiza as regras na ordem em que serão usadas."
    },
    {
      "campo": "resolucao.antes.simbolos",
      "depois": [
        ["at least", "pelo menos, ao menos"],
        ["used to work", "funcionava assim antes (hábito do passado que acabou)"],
        ["shut its doors", "fechou as portas (aqui, deixou de aceitar o lixo)"],
        ["eventually", "finalmente, no fim; falso cognato: 'eventualmente' em português quer dizer 'às vezes'"],
        ["eventualmente", "em português, 'às vezes, de vez em quando'"]
      ],
      "motivo": "Explica o falso cognato nos dois sentidos."
    },
    {
      "campo": "resolucao.pista",
      "depois": "Leia a última frase do 1º parágrafo e a frase do 2º. O texto confirma o que disse antes ou avisa que aquilo só valia até certo ponto?",
      "motivo": "Pergunta mais direta, sem entregar a resposta."
    },
    {
      "campo": "resolucao.passos[0].porque",
      "depois": "A frase diz: 'Ou, pelo menos, era assim que funcionava'. Ela retoma o 1º parágrafo, onde o lixo do Reino Unido ia de navio para a Europa e a Ásia.",
      "motivo": "Voz mais simples e clara."
    },
    {
      "campo": "resolucao.passos[1].porque",
      "depois": "Esse sistema acabou quando a China fechou as portas. Logo, 'at least' põe um limite: era assim só até 2018.",
      "motivo": "Troca 'restringe' por explicação simples."
    },
    {
      "campo": "resolucao.passos[3].faz",
      "depois": "Teste as opções e conclua",
      "motivo": "O passo final também precisa ligar o resultado à letra."
    },
    {
      "campo": "resolucao.passos[3].conta",
      "depois": "“Ou, pelo menos, era assim…” = B",
      "motivo": "Liga a conta à alternativa."
    },
    {
      "campo": "resolucao.erradas.E",
      "depois": "'De forma restrita' seria 'in a restricted way', um modo limitado de agir. Em 'at least', o limite é de tempo ou de mínimo, não do modo de funcionar. Quem marcou E leu 'restringe' como o sentido da expressão, e não como sua função na frase.",
      "motivo": "Diz o que faltou no raciocínio de quem marcou E."
    },
    {
      "campo": "resolucao.erradas.C",
      "depois": "'De certo modo' equivale a 'in a way' e suaviza uma afirmação. O texto não suaviza nada: ele diz que o sistema valia só até 2018. Quem marcou C trocou 'ressalva de tempo' por 'dizer pela metade'.",
      "motivo": "Mostra o que faltou ao aluno que marcou C."
    }
  ],
  "didatica_alertas": [],
  "didatica_ok": true
}
